      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "さよならペンギン",
        "てくてく歩いて笑ってよ",
        "世界に恋して まばたきを",
        "風が通る 風が運ぶ",
        "なみだがおちた",
        "さよならペンギン"
      ]
    }
  ],
  "section": "V1",
  "phrases": [
    {
      "id": "V1-01",
