      "pattern": [
        4,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "灯影浮水面 新芽把春天弹响"
        },
        {
          "id": "V1-02",
          "zh": "你走得快半拍 追着你影子"
        },
        {
          "id": "V1-03",
          "zh": "深夜里桌上吃剩的碎屑 连成梦地图"
        },
        {
          "id": "V1-04",
          "zh": "新的一天 正慢慢靠近"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "水光轻轻跳在新芽上"
        },
        {
          "id": "V1-02",
          "zh": "你脚步匆匆走得早"
        },
        {
          "id": "V1-03",
          "zh": "夜里洒落的碎屑 是梦的地图"
        },
        {
          "id": "V1-04",
          "zh": "新的清晨就要来"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "水光里 跳上新芽时"
        },
        {
          "id": "V1-02",
          "zh": "你稍微 走得快些"
        },
        {
          "id": "V1-03",
          "zh": "深夜的残食 是梦的地图"
        },
        {
          "id": "V1-04",
          "zh": "新的早晨来临"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "水光跃芽尖 夜半的梦还没醒"
        },
        {
          "id": "V1-02",
          "zh": "你稍微快半步 影子轻轻晃"
        },
        {
          "id": "V1-03",
          "zh": "桌上那半夜吃剩的碎屑 拼成梦地图"
        },
        {
          "id": "V1-04",
          "zh": "新的早晨 从梦里走来"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "水面上的光斑跳跃在新芽上"
        },
        {
          "id": "V1-02",
          "zh": "你稍微加快了脚步向前走"
        },
        {
          "id": "V1-03",
          "zh": "夜半里掉落的食物碎屑是梦的地图"
        },
        {
          "id": "V1-04",
          "zh": "崭新的早晨即将到来"
        }
      ]
    }
  ]
}

